const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;
const required = ['application_id', 'dealer_name', 'full_name', 'email'];
const missing = required.filter(f => !body[f]);

if (missing.length) return [{ json: { ok: false, missing, body } }];

return [{
  json: {
    ok: true,
    application_id: body.application_id,
    dealer_name:    body.dealer_name,
    full_name:      body.full_name,
    email:          body.email,
    rejected_at:    body.rejected_at || new Date().toISOString(),
    source:         body.source || null
  }
}];

const d = $("Responder 202 - Aceptado").first().json;
const supabaseResp = $input.first().json;

let adminNotes = "";
let location = "";
if (Array.isArray(supabaseResp)) {
  const row = supabaseResp[0] || {};
  adminNotes = row.admin_notes || "";
  location = [row.location_city, row.location_region].filter(Boolean).join(", ");
}

const notesContext = adminNotes
  ? `\n\nNotas internas del equipo (NO incluyas esto literalmente, úsalo solo como contexto para redactar):\n${adminNotes.slice(0, 800)}`
  : "";

const esVisitaAgencia = d.source === "visita_agencia";
const origenContext = esVisitaAgencia
  ? "\n- Origen: alta gestionada tras una visita presencial de nuestro equipo comercial al showroom (mencionar y agradecer esa visita en el email, con calidez, sin sonar a solicitud fría online)"
  : "";

const briefing = `Eres redactor senior de Black Label Market, marketplace premium de vehículos de alta gama en España.\nEscribe un email de respuesta a una solicitud de alta de showroom que NO ha sido aprobada.\n\nDatos del solicitante:\n- Showroom: ${d.dealer_name}\n- Contacto: ${d.full_name}\n- Email: ${d.email}${location ? "\n- Ubicación: " + location : ""}${origenContext}${notesContext}\n\nEl email debe:\n1. Agradecer el interés${esVisitaAgencia ? " y el tiempo dedicado durante la visita" : " y el tiempo dedicado a rellenar la solicitud"}\n2. Comunicar que la solicitud no encaja con el perfil actual de la plataforma (sin dar razones concretas, de forma educada y profesional)\n3. Dejar la puerta abierta a futuras colaboraciones cuando el showroom amplíe su actividad\n4. Ofrecer que pueden volver a solicitar acceso en el futuro\n5. Firma: "El equipo de Black Label Market"\n\nTono: premium, empático, breve. Sin condescendencia. Sin mencionar motivos específicos de rechazo. Devuelve SOLO el HTML del cuerpo (con <p> y <strong>).`;

return [{
  json: {
    ...d, adminNotes, location,
    openAIRequest: {
      model: $env.OPENAI_MODEL || "gpt-4o-mini",
      max_tokens: 800,
      messages: [{ role: "user", content: briefing }]
    }
  }
}];

const legalFooter = `<div style="margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5">Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href="mailto:privacidad@blacklabelmarket.es">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href="https://blacklabelmarket.es/legal/privacidad">Política de Privacidad</a>.</div>`;

const d = $("Preparar prompt email rechazo").first().json;
const ai = $input.first().json;

let body = "";
if (Array.isArray(ai.choices) && ai.choices[0]) {
  body = ai.choices[0].message?.content || "";
} else if (Array.isArray(ai.content)) {
  body = ai.content.map(b => b.text || "").join("\n").trim();
} else {
  const esVisitaAgencia = d.source === "visita_agencia";
  body = esVisitaAgencia
    ? `<p>Hola ${d.full_name},</p><p>Gracias por la visita y el tiempo dedicado. Tras revisar la solicitud de <strong>${d.dealer_name}</strong>, en este momento no encaja con el perfil actual de la plataforma.</p><p>Quedamos a tu disposición para cualquier consulta futura.</p><p>El equipo de Black Label Market</p>`
    : `<p>Hola ${d.full_name},</p><p>Gracias por tu interés en Black Label Market. Tras revisar la solicitud de <strong>${d.dealer_name}</strong>, en este momento no encaja con el perfil actual de la plataforma.</p><p>Quedamos a tu disposición para cualquier consulta futura.</p><p>El equipo de Black Label Market</p>`;
}

const MAIL_FROM   = $env.MAIL_FROM   || "Black Label Market <hola@blacklabelmarket.es>";
const ADMIN_EMAIL = "marketing@blackseriesagency.es"; // Fijo: notificaciones de Black Label Market siempre a la agencia, nunca al ADMIN_EMAIL compartido con AldeIA (bug real hallado 2026-08-17, ver registro_decisiones.md)

return [{
  json: {
    ...d,
    emailPayload: {
      from: MAIL_FROM, to: [d.email],
      subject: "Respuesta a tu solicitud - Black Label Market",
      html: body + legalFooter
    },
    slackText: `*❌ Solicitud rechazada*\n\n*Showroom:* ${d.dealer_name}\n*Contacto:* ${d.full_name} (${d.email})\n*Email de rechazo:* enviado`
  }
}];
